<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway;

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessToken;

class DcrInitialAccessTokenCursor
{
    public const string DESCRIPTION_ASC = 'description';
    public const string DESCRIPTION_DESC = '-description';

    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
        private ?string $sinceDescription = null,
        private ?array $order = null,
    ) {
    }
    public function next(DcrInitialAccessToken $dcrInitialAccessToken, ?int $size): DcrInitialAccessTokenCursor
    {
        $next = clone $this;
        $next->sinceUid = $dcrInitialAccessToken->uid();
        $next->sinceDescription = $dcrInitialAccessToken->getDescription();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function withLimit(int $limit): DcrInitialAccessTokenCursor
    {
        $next = clone $this;
        $next->limit = $limit;
        return $next;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
    public function sinceDescription(): ?string
    {
        return $this->sinceDescription;
    }
    public function order(): ?array
    {
        return $this->order;
    }
}
